// Start reports when due and continues at four-hour intervals until cancellation.
func (r *Reporter) Start(ctx context.Context) {
    if r == nil { return }
    go func() {
        for {
            r.mu.Lock()
            last, _ := time.Parse(time.RFC3339, r.state.LastTimestamp)
            r.mu.Unlock()
            delay := time.Until(last.Add(interval))
            if delay < 0 { delay = 0 }
            timer := time.NewTimer(delay)
            select {
            case <-ctx.Done():
                if !timer.Stop() { select { case <-timer.C: default: } }
                return
            case <-timer.C:
            }
            if err := r.Report(ctx); err != nil && ctx.Err() == nil {
                r.logger.Warnf("reporting telemetry: %v", err)
                // Retry on the next interval rather than looping immediately.
                timer = time.NewTimer(interval)
                select {
                case <-ctx.Done():
                    if !timer.Stop() { select { case <-timer.C: default: } }
                    return
                case <-timer.C:
                }
            }
